import React from 'react';

function ChambrePage() {
  return (
    <div className="p-4">
      <h1 className="text-2xl font-bold text-blue-500">Page des Chambres</h1>
      <p>Ici sera affichée la liste des chambres.</p>
    </div>
  );
}

export default ChambrePage;
